const fs = await import('node:fs');
const path = await import('node:path');
const imgPath = globalThis.input.image_path;
const outPath = globalThis.input.output_path;
if (!fs.existsSync(imgPath)) {
  throw new Error('Input image not found: ' + imgPath);
}
const outDir = path.dirname(outPath);
if (!fs.existsSync(outDir)) {
  fs.mkdirSync(outDir, { recursive: true });
}
globalThis.imgPath = imgPath;
globalThis.outPath = outPath;

const fs = await import('node:fs');
const { PDFDocument } = await import('pdf-lib');
const imgPath = globalThis.imgPath;
const outPath = globalThis.outPath;
const imgBytes = fs.readFileSync(imgPath);
const pdfDoc = await PDFDocument.create();
const page = pdfDoc.addPage([600, 800]);
let image;
const ext = imgPath.toLowerCase();
if (ext.endsWith('.png')) {
  image = await pdfDoc.embedPng(imgBytes);
} else if (ext.endsWith('.jpg') || ext.endsWith('.jpeg')) {
  image = await pdfDoc.embedJpg(imgBytes);
} else {
  throw new Error('Unsupported image format: ' + ext);
}
const { width, height } = image.scale(1);
const x = (600 - width) / 2;
const y = (800 - height) / 2;
page.drawImage(image, { x, y, width, height });
const pdfBytes = await pdfDoc.save();
fs.writeFileSync(outPath, pdfBytes);
globalThis.pdfPath = outPath;
globalThis.sizeBytes = pdfBytes.length;

const result = {
  pdf_path: globalThis.pdfPath,
  size_bytes: globalThis.sizeBytes
};
console.log(JSON.stringify(result));
